import{_ as n,l as i,o as e,c as l,v as r,p as E,x as t,d as s,i as d,S as h}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"基准与跟踪误差","description":"","frontmatter":{"title":"基准与跟踪误差","date":"2026-09-08T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/benchmark-tracking-error.md","filePath":"quant/benchmark-tracking-error.md","lastUpdated":1789023840000}'),p={name:"quant/benchmark-tracking-error.md"};function c(m,a,B,T,_,u){const o=i("Mermaid");return e(),l("div",null,[a[1]||(a[1]=r('<h1 id="基准与跟踪误差" tabindex="-1">基准与跟踪误差 <a class="header-anchor" href="#基准与跟踪误差" aria-label="Permalink to &quot;基准与跟踪误差&quot;">​</a></h1><div class="epigraph"><p>跟踪误差约束把组合钉在基准附近：优化的对象变成相对方差，而不是绝对方差；约束绑得越紧，越难把观点写成有意义的主动权重。</p><footer>—— Roll, A Mean/Variance Analysis of Tracking Error, Journal of Portfolio Management, 1992；风险预算语言对照 Litterman, Hot Spots and Hedges</footer></div><p><a href="/quant/fund-flows-chasing">上一课</a>说明资金在产品之间流动。要评价主动，必须先指定<strong>基准与允许偏离</strong>。跟踪误差（TE）是主动收益 \\(R_p-R_b\\) 的波动，见 <a href="/quant/ir-sharpe">IR/Sharpe</a> 的分母。Roll（1992）与 Jorion 指出：在 TE 约束下做均值方差，最优解一般不是无约束有效前沿上的点。Litterman 的热点与对冲把主动风险拆到名字与因子上，供预算而不是供又一次 <a href="/quant/capm">CAPM</a> 检验。130/30 与指数增强的产品契约就是这条约束。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>基准不可投资（含未上市、含税差异、含当日不可借的成分）时，TE 是会计数字，不是可对冲风险。基准选错（用大盘评小盘基金）会把风格暴露叫做 IR。问题是合同：基准必须可投资、与费用与分红处理一致，TE 限额要同时管因子与残差。指数调仓周的被动流会暂时抬高 TE；那是规则，不是经理「失去控制」，见 <a href="/quant/index-inclusion-passive-flow">指数纳入</a>。</p><p>最小化 TE 而不管超额，会复制基准加噪声，主动份额接近零（下课）。最小化 TE 同时强加观点，观点会挤在少数无约束的方向上——Litterman 热点出现的地方。</p><h3 id="相对最优不是绝对最优" tabindex="-1">相对最优不是绝对最优 <a class="header-anchor" href="#相对最优不是绝对最优" aria-label="Permalink to &quot;相对最优不是绝对最优&quot;">​</a></h3><p>Roll 的几何：TE 约束是以基准为球心的椭球，切点组合一般不是市场组合或 Markowitz 切点。用绝对夏普评价 TE 产品是改契约。用 TE 评价绝对收益对冲基金同样改契约。</p><p><span class="marginnote">Black–Litterman 把观点与均衡收益混合，输出的是绝对权重；再加 TE 约束，等于把 BL 观点投影到基准的邻域。投影会削掉观点的一大部分，IR 预期必须跟着降。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>定义：\\(x_t=R_{p,t}-R_{b,t}\\)，\\(\\mathrm{TE}=\\sigma(x)\\sqrt{q}\\)。分解：因子 TE vs 特异 TE，用 <a href="/quant/fundamental-risk-model">基本面风险模型</a>。优化：\\(\\max w^\\top\\alpha-\\lambda(w-w_b)^\\top\\Sigma(w-w_b)\\) 加约束。报告：事前预测 TE vs 事后实现，含调仓周。热点：贡献主动方差最多的名字，对照限额。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>投资人用基准做委托与比较。TE 是代理成本的可观测上限。绑得越紧，技能越难表达，费用越像浪费——除非契约本来就是增强指数。被动流迫使大家在同一天交易，实现 TE 有事件簇，不能当 IID 去年化。</p>',13)),(e(),E(h,null,{default:t(()=>[d(o,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20Bench%5B%22%E5%8F%AF%E6%8A%95%E8%B5%84%E5%9F%BA%E5%87%86%22%5D%20--%3E%20TE%5B%22%E8%B7%9F%E8%B8%AA%E8%AF%AF%E5%B7%AE%E9%99%90%E9%A2%9D%22%5D%0A%20%20View%5B%22%E8%A7%82%E7%82%B9%E4%B8%8E%20BL%22%5D%20--%3E%20Proj%5B%22%E6%8A%95%E5%BD%B1%E5%88%B0%E5%9F%BA%E5%87%86%E9%82%BB%E5%9F%9F%22%5D%0A%20%20TE%20--%3E%20Proj%0A%20%20Proj%20--%3E%20Hot%5B%22%E7%83%AD%E7%82%B9%E5%90%8D%E5%AD%97%E4%B8%8E%E5%9B%A0%E5%AD%90%22%5D%0A%20%20Flow%5B%22%E8%B0%83%E4%BB%93%E4%B8%8E%E7%94%B3%E8%B5%8E%22%5D%20--%3E%20Real%5B%22%E4%BA%8B%E5%90%8E%20TE%20%E4%BA%8B%E4%BB%B6%E7%B0%87%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写如何用基准切换操纵业绩。自定义基准若不可投资，IR 不可信。下一课：TE 高不等于持股与指数不同。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>TE 产品应用相对风险评价，不要用绝对夏普改契约。</li><li>基准必须可投资；约束把观点投影到热点上。</li><li>调仓周的 TE 是被动流，不是经理失控。</li><li>出处：Roll, <em>JPM</em>, 1992；Jorion 对 TE 约束优化；Litterman, Hot Spots and Hedges。</li></ul>',4))])}const q=n(p,[["render",c]]);export{f as __pageData,q as default};
